using UnityEngine;

public class HeadgearItem : Item
{
	protected GameObject headgearPrefab;

	public Headgear curHeadgear;

	public override void Activate()
	{
		if (!(headgearPrefab == null) && !(parentEntity == null))
		{
			curHeadgear = Globals.ChaosInst<Headgear>(headgearPrefab, (!parentEntity.headPosition) ? parentEntity.transform : parentEntity.headPosition.transform);
			curHeadgear.Initialize(parentEntity, ID);
		}
	}

	public override void Deactivate()
	{
		if (!(curHeadgear == null))
		{
			curHeadgear.Hide(destroyOnHide: true);
		}
	}
}
=== GroupItem
using System;
using System.Collections.Generic;

public class GroupItem : Item
{
	public Inventory itemInven;

	private bool updateInfoStr = true;

	private string infoStr = string.Empty;

	public int Count => itemInven.Count;

	public string InfoStr
	{
		get
		{
			if (updateInfoStr)
			{
				updateInfoStr = false;
				infoStr = string.Empty;
				if (GroupItemManager.groupsDict.ContainsKey(ID))
				{
					foreach (string item in GroupItemManager.groupsDict[ID])
					{
						if (itemInven.ContainsItem(item))
						{
							infoStr = infoStr + "+ " + TextManager.GetItemName(item) + "\n";
						}
					}
				}
			}
			return infoStr;
		}
	}

	protected override string ExtraInfo => InfoStr;

	public string CompletionProgStr
	{
		get
		{
			string result;
			if (GroupItemManager.groupsDict.ContainsKey(ID))
			{
				result = ((GroupItemManager.groupsDict[ID].Count != itemInven.Count) ? ("  (" + itemInven.Count + "/" + GroupItemManager.groupsDict[ID].Count + ")") : " ★");
			}
			else
			{
				result = string.Empty;
			}
			return result;
		}
	}

	public GroupItem()
	{
		combineOnly = true;
		isGroupItem = true;
		destroyOnDrop = true;
		useSimpleInfo = true;
	}

	public override void Activate()
	{
		SetStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetStatus(givenStatus: false);
	}

	public virtual void SetStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			if (itemInven == null)
			{
				itemInven = new Inventory(parentPlayer);
			}
			Inventory inventory = parentPlayer.inventory;
			inventory.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Remove(inventory.inventoryChangeEventHandler, new Inventory.ItemEventHandler(HandleGrouping));
			Inventory inventory2 = itemInven;
			inventory2.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Remove(inventory2.inventoryChangeEventHandler, new Inventory.ItemEventHandler(OnInternalInvenChange));
			if (givenStatus)
			{
				Inventory inventory3 = parentPlayer.inventory;
				inventory3.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Combine(inventory3.inventoryChangeEventHandler, new Inventory.ItemEventHandler(HandleGrouping));
				Inventory inventory4 = itemInven;
				inventory4.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Combine(inventory4.inventoryChangeEventHandler, new Inventory.ItemEventHandler(OnInternalInvenChange));
				HandleGrouping(null, givenStatus: true);
			}
			else
			{
				HandleDrop();
			}
		}
	}

	public virtual void OnInternalInvenChange(Item givenItem, bool givenStatus)
	{
		parentPlayer.inventory.AnnounceItemEvent(givenItem, givenStatus);
	}

	public virtual void HandleGrouping(Item givenItem, bool givenStatus)
	{
		if (!givenStatus || !GroupItemManager.groupsDict.ContainsKey(ID))
		{
			return;
		}
		foreach (string item in GroupItemManager.groupsDict[ID])
		{
			if (parentPlayer.inventory.ContainsItem(item))
			{
				parentPlayer.inventory.RemoveItem(item);
				if (!itemInven.ContainsItem(item))
				{
					itemInven.AddItem(item);
					updateInfoStr = true;
				}
			}
		}
	}

	public virtual void HandleDrop(bool ignoreDrop = false)
	{
		if (!GroupItemManager.groupsDict.ContainsKey(ID))
		{
			return;
		}
		updateInfoStr = true;
		if (!ignoreDrop && !parentPlayer.IsDead)
		{
			string empty = string.Empty;
			List<string> itemIDList = itemInven.GetItemIDList();
			for (int num = itemIDList.Count - 1; num >= 0; num--)
			{
				empty = itemIDList[num];
				itemInven.DropItem(itemIDList[num]);
			}
		}
		itemInven.ClearInventory();
	}
}
=== ElementalStatusUp
public class ElementalStatusUp : Item
{
	private string statStr;

	private NumVarStatMod statusEffectUpMod;

	protected override string ExtraInfo => PercentToStr(statusEffectUpMod, "+");

	public ElementalStatusUp(string givenID, ElementType givenElement, float givenValue = 0.0625f)
	{
		ID = givenID;
		category = Category.Offense;
		statStr = ElementToStatusEffect(givenElement);
		statusEffectUpMod = new NumVarStatMod(ID, givenValue);
		parentGroupID = StatusChanceUpGroupItem.staticID;
	}

	private string ElementToStatusEffect(ElementType element)
	{
		return element switch
		{
			ElementType.Fire => StatData.burnChStr, 
			ElementType.Air => StatData.slowChStr, 
			ElementType.Earth => StatData.psnChStr, 
			ElementType.Lightning => StatData.shockChStr, 
			ElementType.Water => StatData.frzChStr, 
			_ => string.Empty, 
		};
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if ((!givenStatus || !GroupItemCreated(StatusChanceUpGroupItem.staticID)) && SetParentAsPlayer())
		{
			StatManager.ModifyAllStatData(statusEffectUpMod, parentSkillCategory, statStr, IgnoreStatusConditional, givenStatus);
		}
	}
}
=== ElementalStatusImmune
public class ElementalStatusImmune : Item
{
	private ElementType element;

	private BoolVarStatMod statMod;

	public ElementalStatusImmune(string givenID, ElementType givenElement)
	{
		ID = givenID;
		category = Category.Defense;
		parentGroupID = ImmuneGroupItem.staticID;
		element = givenElement;
		statMod = new BoolVarStatMod(givenID, newModValue: true, 5);
	}

	public override void Activate()
	{
		SetStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetStatus(givenStatus: false);
	}

	private void SetStatus(bool givenStatus)
	{
		if ((!givenStatus || !GroupItemCreated(ImmuneGroupItem.staticID)) && !(parentEntity == null))
		{
			switch (element)
			{
			case ElementType.Fire:
				parentEntity.health.ignoreBurn.Modify(statMod, givenStatus);
				break;
			case ElementType.Air:
				parentEntity.health.ignoreSlow.Modify(statMod, givenStatus);
				break;
			case ElementType.Earth:
				parentEntity.health.ignorePoison.Modify(statMod, givenStatus);
				break;
			case ElementType.Lightning:
				parentEntity.health.ignoreShock.Modify(statMod, givenStatus);
				break;
			case ElementType.Water:
				parentEntity.health.ignoreFreeze.Modify(statMod, givenStatus);
				break;
			}
		}
	}
}
=== ElementalStatusLevelUp
public class ElementalStatusLevelUp : Item
{
	private ElementType element;

	private string statusLevelStr;

	private NumVarStatMod statusLevelUpMod;

	public ElementalStatusLevelUp(string givenID, ElementType givenElement, int givenLevelInc = 1)
	{
		ID = givenID;
		category = Category.Offense;
		element = givenElement;
		statusLevelStr = ElementToStatusLevel(element);
		statusLevelUpMod = new NumVarStatMod(ID, givenLevelInc);
	}

	private string ElementToStatusLevel(ElementType element)
	{
		return element switch
		{
			ElementType.Fire => "burnLevel", 
			ElementType.Air => "slowLevel", 
			ElementType.Earth => "poisonLevel", 
