			Inventory inventory = currentInv;
			inventory.itemAddEventHandler = (Inventory.SingleEventHandler)Delegate.Remove(inventory.itemAddEventHandler, new Inventory.SingleEventHandler(OnInventoryChange));
			if (givenStatus)
			{
				ReplaceItems();
				Inventory inventory2 = currentInv;
				inventory2.itemAddEventHandler = (Inventory.SingleEventHandler)Delegate.Combine(inventory2.itemAddEventHandler, new Inventory.SingleEventHandler(OnInventoryChange));
			}
			else
			{
				SetModStatus(givenStatus: false);
			}
		}
