	private void OnInventoryChange(Item givenItem)
	{
		if (currentInv.CursedCount < 12)
		{
			if (!IsKeptItem(givenItem))
			{
				ReplaceItems();
			}
			else
			{
				SetModStatus(givenStatus: true, currentInv.CursedCount);
			}
		}
	}

	private void ReplaceItems()
	{
		int num = 0;
		foreach (Item value in currentInv.itemDict.Values)
		{
			if (IsTrueCombineOnly(value))
			{
				value.isCursed = true;
			}
			if (!IsKeptItem(value))
			{
				if (value.isGroupItem)
				{
					num += (value as GroupItem).Count;
					(value as GroupItem).HandleDrop(ignoreDrop: true);
				}
				else
				{
					num++;
				}
			}
		}
		currentInv.ClearInventory(IsKeptItem);
		SetModStatus(givenStatus: true, currentInv.CursedCount + num);
		int num2 = 3;
		for (int i = 0; i < num; i++)
		{
			if (currentInv.Count >= 12)
			{
				break;
			}
			string availableItemID = LootManager.GetAvailableItemID(1f);
			if (availableItemID != string.Empty && !currentInv.ContainsItem(availableItemID))
			{
				currentInv.AddItem(availableItemID, showNotice: true);
			}
			else if (num2 > 0)
			{
				num2--;
				i--;
			}
		}
	}

