		{
			if (activeTimer.IsRunning)
			{
				activeTimer.Refresh();
			}
			else
			{
				healedAmount = 0;
				maxHealAmount = 0;
				activeTimer.IsRunning = true;
			}
			maxHealAmount += Mathf.CeilToInt((float)givenAtkInfo.damage * 0.75f);
			if (!isRunningCoroutine)
			{
				parentPlayer.StartCoroutine(HandleRetributionWindow());
			}
		}
	}

	private IEnumerator HandleRetributionWindow()
	{
		isRunningCoroutine = true;
		UpdateItemBar(ItemStatusBar.ItemState.Active);
		Health.globalTakeDamageActualHandlers = (Health.GlobalOnTakeDamageHandler)Delegate.Remove(Health.globalTakeDamageActualHandlers, new Health.GlobalOnTakeDamageHandler(OnHitEnemyEvent));
		Health.globalTakeDamageActualHandlers = (Health.GlobalOnTakeDamageHandler)Delegate.Combine(Health.globalTakeDamageActualHandlers, new Health.GlobalOnTakeDamageHandler(OnHitEnemyEvent));
		while (activeTimer.IsRunning)
		{
			yield return null;
		}
		Health.globalTakeDamageActualHandlers = (Health.GlobalOnTakeDamageHandler)Delegate.Remove(Health.globalTakeDamageActualHandlers, new Health.GlobalOnTakeDamageHandler(OnHitEnemyEvent));
		UpdateItemBar(ItemStatusBar.ItemState.Ready);
