		{
			return;
		}
		if (healedAmount >= maxHealAmount)
		{
			activeTimer.IsRunning = false;
			return;
		}
		healValue = Mathf.CeilToInt((float)givenAtkInfo.damage * 0.1f);
		modHealVal = Mathf.CeilToInt((float)healValue * parentPlayer.health.healModifierStat.CurrentValue);
		if (modHealVal + healedAmount > maxHealAmount)
		{
			healValue = Mathf.CeilToInt((float)(maxHealAmount - healedAmount) / parentPlayer.health.healModifierStat.CurrentValue);
		}
		parentEntity.health.RestoreHealth(healValue);
		healedAmount += Mathf.CeilToInt(modHealVal);
	}
