using UnityEngine;

public class RootShield : OnTakeDamageItem
{
	public static string staticID = "RootShield";

	private static int spawnCount = 5;

	private static float innerRange = 1.75f;

	private static float outerRange = 3.25f;

	private VineTrap currentVT;

	private WaitForSeconds waitForDelay = new WaitForSeconds(0.0625f);

	private ChaosQuickStopwatch cooldownStopwatch = new ChaosQuickStopwatch(16f);

	private bool itemHeld;

	private static Vector2[] spawnOffsets;

	private static Vector2[] SpawnOffsets
	{
		get
		{
			if (spawnOffsets == null)
			{
				spawnOffsets = new Vector2[spawnCount * 3];
				for (int i = 0; i < spawnCount; i++)
				{
					Vector2 circlePositionVector = Globals.GetCirclePositionVector(spawnCount, i);
					int num = i * 3;
					ref Vector2 reference = ref spawnOffsets[num];
					reference = circlePositionVector * innerRange;
					ref Vector2 reference2 = ref spawnOffsets[num + 1];
					reference2 = circlePositionVector * outerRange;
					ref Vector2 reference3 = ref spawnOffsets[num + 2];
					reference3 = -spawnOffsets[num + 1];
				}
			}
			return spawnOffsets;
		}
	}

	public RootShield()
	{
		ID = staticID;
		category = Category.Defense;
		activateOnActual = true;
	}

	public override void Activate()
	{
		base.Activate();
		itemHeld = true;
		SetItemBarStatus();
	}

	public override void Deactivate()
	{
		base.Deactivate();
		itemHeld = false;
		SetItemBarStatus();
	}

	public override void OnTakeDamageActual(AttackInfo givenInfo, Entity givenEnt)
	{
		if (!(parentEntity == null) && !cooldownStopwatch.IsRunning)
		{
			parentEntity.StartCoroutine(SpawnAllTraps(parentEntity.transform.position));
			parentEntity.StartCoroutine(StartCooldownTimer());
		}
	}

	private IEnumerator SpawnAllTraps(Vector2 givenPosition)
	{
		for (int i = 0; i < spawnCount * 3; i++)
		{
			if (i % 3 == 0)
			{
				yield return waitForDelay;
			}
			CreateVineTrap(givenPosition + SpawnOffsets[i]);
		}
	}

	private void CreateVineTrap(Vector2 givenPosition)
	{
		if (Globals.CheckCircle(givenPosition, 0.25f, ChaosCollisions.layerAll))
		{
			currentVT = Globals.ChaosInst<VineTrap>(VineTrap.Prefab, null, givenPosition);
			currentVT.attack.SetAttackInfo(parentSkillCategory, ID);
			currentVT.useLifeTime = true;
		}
	}

	private void SetItemBarStatus()
	{
		if (!itemHeld)
		{
			RemoveFromItemBar();
		}
		else if (cooldownStopwatch.IsRunning)
		{
			UpdateItemBar(ItemStatusBar.ItemState.Disabled);
		}
		else
		{
			UpdateItemBar(ItemStatusBar.ItemState.Active);
		}
	}

	private IEnumerator StartCooldownTimer()
	{
		cooldownStopwatch.IsRunning = true;
		SetItemBarStatus();
		while (cooldownStopwatch.IsRunning)
		{
			yield return null;
		}
		SetItemBarStatus();
	}
}
