public class SequenceDefense : OnTakeDamageItem
{
	public static string staticID = "SequenceDefense";

	private NumVarStatMod armorMod;

	private string[] atkHistory;

	private int atkIndexMax = 3;

	private int atkIndex;

	private bool modApplied;

	protected override string ExtraInfo => PercentToStr(armorMod, "-");

	public SequenceDefense()
	{
		ID = staticID;
		category = Category.Defense;
		activateOnEnter = true;
		activateOnActual = true;
		armorMod = new NumVarStatMod(ID, 0.25f);
		atkHistory = new string[atkIndexMax];
	}

	public override void Activate()
	{
		InitHistory();
		base.Activate();
	}

	public override void OnTakeDamageEnter(AttackInfo givenAtkInfo, Entity givenEnt)
	{
		if (givenAtkInfo != null && givenAtkInfo.damage > 0 && !givenAtkInfo.isStatusEffect)
		{
			modApplied = CheckHistory(givenAtkInfo.attackInfoKey);
			if (modApplied)
			{
				parentEntity.health.armorStat.AddMod(armorMod);
			}
		}
	}

	public override void OnTakeDamageActual(AttackInfo givenAtkInfo, Entity givenEnt)
	{
		if (modApplied)
		{
			parentEntity.health.armorStat.RemoveMod(armorMod);
		}
	}

	private void InitHistory()
	{
		atkIndex = 0;
		for (int i = 0; i < atkIndexMax; i++)
		{
			atkHistory[i] = string.Empty;
		}
	}

	private bool CheckHistory(string givenKey)
	{
		for (int i = 0; i < atkIndexMax; i++)
		{
			if (atkHistory[i] == givenKey)
			{
				return true;
			}
		}
		atkHistory[atkIndex] = givenKey;
		atkIndex = (atkIndex + 1) % atkIndexMax;
		return false;
	}
}

