using System;
using System.Collections.Generic;
using UnityEngine;

public class SevenFlush : Item
{
	protected ElementType element;

	protected string elementStr;

	protected bool isActive;

	protected bool setActive;

	protected int modPriority = 5;

	private Player.SkillState currentSS;

	private NevesAura nevesAura;

	private NumVarStatMod outfitPaletteMod;

	private Dictionary<ElementType, Color> outlineDict = new Dictionary<ElementType, Color>
	{
		{
			ElementType.Fire,
			new Color(1f, 0f, 0f, 0.25f)
		},
		{
			ElementType.Air,
			new Color(0.5f, 0.8f, 0.8f, 0.25f)
		},
		{
			ElementType.Earth,
			new Color(0f, 0.47f, 0f, 0.25f)
		},
		{
			ElementType.Lightning,
			new Color(1f, 0.78f, 0f, 0.25f)
		},
		{
			ElementType.Water,
			new Color(0.313f, 0.537f, 0.9f, 0.25f)
		}
	};

	private Dictionary<ElementType, int> paletteDict = new Dictionary<ElementType, int>
	{
		{
			ElementType.Fire,
			27
		},
		{
			ElementType.Air,
			28
		},
		{
			ElementType.Earth,
			29
		},
		{
			ElementType.Lightning,
			30
		},
		{
			ElementType.Water,
			31
		}
	};

	public SevenFlush(string givenID, ElementType givenElement)
	{
		ID = givenID;
		notForSale = true;
		element = givenElement;
		elementStr = givenElement.ToString();
		outfitPaletteMod = new NumVarStatMod(ID, 27f, 2, VarStatModType.Override);
	}

	public override void Activate()
	{
		if (SetParentAsPlayer())
		{
			UpdateItemBar(ItemStatusBar.ItemState.Disabled);
			CheckActivate();
			SetEventHandlers(givenStatus: true);
		}
	}

	public override void Deactivate()
	{
		if (nevesAura != null)
		{
			nevesAura.Reset();
		}
		if (SetParentAsPlayer())
		{
			RemoveFromItemBar();
			ApplyMods(givenStatus: false);
			ToggleOutfit(givenStatus: false);
			SetEventHandlers(givenStatus: false);
			isActive = false;
		}
	}

	private void SetEventHandlers(bool givenStatus)
	{
		Player player = parentPlayer;
		player.skillChangedEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillChangedEventHandlers, new Player.SkillEventHandler(OnSkillChanged));
		if (givenStatus)
		{
			Player player2 = parentPlayer;
			player2.skillChangedEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player2.skillChangedEventHandlers, new Player.SkillEventHandler(OnSkillChanged));
		}
	}

	private void OnSkillChanged(Player.SkillState ss)
	{
		CheckActivate();
	}

	private void CheckActivate()
	{
		if (parentPlayer == null)
		{
			return;
		}
		setActive = true;
		for (int i = 0; i < parentPlayer.assignedSkills.Length; i++)
		{
			currentSS = parentPlayer.assignedSkills[i];
			if (currentSS == null || currentSS.element != element)
			{
				setActive = false;
				break;
			}
		}
		if (setActive && (parentPlayer.stockSkill == null || parentPlayer.stockSkill.element != element))
		{
			setActive = false;
		}
		if (isActive != setActive)
		{
			isActive = setActive;
			if (isActive)
			{
				UpdateItemBar(ItemStatusBar.ItemState.Active);
			}
			else
			{
				UpdateItemBar(ItemStatusBar.ItemState.Disabled);
			}
			ApplyMods(isActive);
			ToggleOutfit(isActive);
		}
	}

	private Color GetOutfitColor(ElementType element)
	{
		return (!(parentPlayer != null) || !outlineDict.ContainsKey(element)) ? Globals.transparentColor : outlineDict[element];
	}

	private int GetPaletteIndex(ElementType element)
	{
		if (parentPlayer == null)
		{
			return 0;
		}
		if (outlineDict.ContainsKey(element))
		{
			return paletteDict[element];
		}
		return 0;
	}

	private void ToggleOutfit(bool givenStatus)
	{
		outfitPaletteMod.modValue = GetPaletteIndex(element);
		parentPlayer.SetPlayerOutfitColor(outfitPaletteMod, givenStatus);
		parentPlayer.OutlineColorDisabled = ((!givenStatus) ? Player.OutlineColorDisabledDefault : GetOutfitColor(element));
		if (parentPlayer.spriteRenderer != null)
		{
			if (!parentPlayer.overdriveReady)
			{
				parentPlayer.spriteRenderer.material.SetColor("_OutlineColor", parentPlayer.OutlineColorDisabled);
			}
			if (givenStatus && nevesAura == null)
			{
				nevesAura = NevesAura.Create(parentPlayer, parentPlayer.spriteRenderer.transform, element);
			}
		}
		if (nevesAura != null)
		{
			nevesAura.SetStatus(givenStatus);
		}
	}

	public virtual void ApplyMods(bool givenStatus)
	{
	}

	public bool ElementAndStatusConditional(StatData givenSD)
	{
		return IgnoreStatusConditional(givenSD) && givenSD.GetValue<string>(StatData.eleStr) == elementStr;
	}
}
