		}
		currentSI = null;
		if (storeItem is ItemStoreItem)
		{
			ItemStoreItem itemStoreItem = (ItemStoreItem)storeItem;
			if (itemStoreItem.cursedOnly || itemStoreItem.usePlatinumCost || (itemStoreItem.disablePriceMarker && itemStoreItem.Cost == 0))
			{
				return;
			}
			UnityEngine.Object.Destroy(itemStoreItem.priceMarker.gameObject);
			currentSI = Globals.ChaosInst<StoreItem>(ItemMerchant.PrefabDict[ItemMerchant.itemPrefabName], itemStoreItem.transform.parent, itemStoreItem.transform.position);
			(currentSI as ItemStoreItem).disableMarkerOffset = itemStoreItem.disableMarkerOffset;
		}
		else if (storeItem is SkillStoreItem)
		{
			SkillStoreItem skillStoreItem = (SkillStoreItem)storeItem;
			if (skillStoreItem.usePlatinumCost || (skillStoreItem.disablePriceMarker && skillStoreItem.Cost == 0))
			{
				return;
