			currentSI = Globals.ChaosInst<StoreItem>(SkillStoreItem.Prefab, skillStoreItem.transform.parent, skillStoreItem.transform.position);
		}
		if (currentSI != null)
		{
			currentSI.GetComponent<SortSpriteLayer>().yValueOffset = storeItem.GetComponent<SortSpriteLayer>().yValueOffset;
			currentSI.disablePriceMarker = storeItem.disablePriceMarker;
			currentSI.priceMarkerYOffset = storeItem.priceMarkerYOffset;
