using System.Collections;
using UnityEngine;

public class StunShield : OnTakeDamageItem
{
	public static string staticID = "StunShield";

	private ChaosQuickStopwatch cdStopwatch = new ChaosQuickStopwatch(16f);

	private bool itemHeld;

	public StunShield()
	{
		ID = staticID;
		category = Category.Defense;
		activateOnActual = true;
	}

	public override void Activate()
	{
		if (SetParentAsPlayer())
		{
			base.Activate();
			itemHeld = true;
			SetItemBarStatus();
		}
	}

	public override void Deactivate()
	{
		base.Deactivate();
		itemHeld = false;
		SetItemBarStatus();
	}

	public override void OnTakeDamageActual(AttackInfo givenInfo, Entity givenEnt)
	{
		if (!(parentPlayer == null) && !cdStopwatch.IsRunning)
		{
			parentPlayer.StartCoroutine(StartCooldownTimer());
			Vector2 vector = parentPlayer.attackOriginTrans.position;
			Globals.ChaosInst<StunBurst>(StunBurst.Prefab, null, vector).attack.SetAttackInfo(parentSkillCategory, ID);
			ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("SparkleAura");
			poolItem.Emit(7, vector);
			poolItem.Emit(3, vector + Random.insideUnitCircle * 2f);
			poolItem.Emit(3, vector + Random.insideUnitCircle * 2f);
		}
	}

	private void SetItemBarStatus()
	{
		if (!itemHeld)
		{
			RemoveFromItemBar();
		}
		else if (cdStopwatch.IsRunning)
		{
			UpdateItemBar(ItemStatusBar.ItemState.Disabled);
		}
		else
		{
			UpdateItemBar(ItemStatusBar.ItemState.Active);
		}
	}

	private IEnumerator StartCooldownTimer()
	{
		cdStopwatch.IsRunning = true;
		SetItemBarStatus();
		while (cdStopwatch.IsRunning)
		{
			yield return null;
		}
		SetItemBarStatus();
	}
}

