	public virtual void SetModStatus(bool givenStatus)
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			player.degenHealth.Modify(degenMod, givenStatus);
			player.skillEnterEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillEnterEventHandlers, new Player.SkillEventHandler(OnSkillEnter));
			player.skillExitEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillExitEventHandlers, new Player.SkillEventHandler(OnSkillExit));
			if (givenStatus)
			{
				player.skillEnterEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player.skillEnterEventHandlers, new Player.SkillEventHandler(OnSkillEnter));
				player.skillExitEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player.skillExitEventHandlers, new Player.SkillEventHandler(OnSkillExit));
			}
		}
		Health.globalTakeDamageActualHandlers = (Health.GlobalOnTakeDamageHandler)Delegate.Remove(Health.globalTakeDamageActualHandlers, new Health.GlobalOnTakeDamageHandler(OnDamageDealt));
		if (givenStatus)
		{
			Health.globalTakeDamageActualHandlers = (Health.GlobalOnTakeDamageHandler)Delegate.Combine(Health.globalTakeDamageActualHandlers, new Health.GlobalOnTakeDamageHandler(OnDamageDealt));
		}
	}

	private void OnSkillEnter(Player.SkillState givenSkill)
	{
		ModifySkill(givenSkill, givenStatus: true);
	}

	private void OnSkillExit(Player.SkillState givenSkill)
	{
		ModifySkill(givenSkill, givenStatus: false);
	}

	private void ModifySkill(Player.SkillState givenSkill, bool givenStatus)
	{
		if (givenSkill != null)
		{
			if (givenStatus)
			{
				damageMod.modValue = Mathf.Clamp01(1f - givenSkill.parent.health.HealthPercentage);
				givenSkill.skillData.AddMod(StatData.damageStr, damageMod);
			}
			else
			{
				givenSkill.skillData.RemoveMod(StatData.damageStr, damageMod.ID);
			}
		}
	}

	private void OnDamageDealt(AttackInfo givenAtkInfo, Entity atkEntity, Entity hurtEntity)
	{
		if (!(atkEntity == null) && atkEntity is Player && !(hurtEntity is Destructible) && !(hurtEntity is Pinata) && givenAtkInfo != null && !givenAtkInfo.isStatusEffect)
		{
			healAmount = (int)((float)givenAtkInfo.damage * vampRate);
			if (healAmount > 0 && atkEntity.health.CurrentHealthValue > 0 && !atkEntity.fsm.currentStateName.Contains("Dead"))
			{
				atkEntity.health.RestoreHealth(healAmount);
			}
		}
	}
}
